#include <iostream>

int main() {
    const int disponibles = 11;
    int usados = 3;
    const int antes = usados;
    usados = usados + 4;
    const int libres = disponibles - usados;
    const bool queda_espacio = libres > 0;
    if (queda_espacio) {
        std::cout << "Free: " << libres << "\n";
    } else {
        std::cout << "Complete\n";
    }
    std::cout << "Before: " << antes;
    return 0;
}

